    text = read_source(path)
    lines = text.split('\n')
    _check_pos(lines, line, col)
    cl = lines[line - 1]
    s, e = _cursor_ident(cl, col)
    ident = cl[s:e]
    offset = sum(len(lines[k]) + 1 for k in range(line - 1)) + s
